import csv,json
from pathlib import Path
p=Path('product_catalog/C-tvs-video-home-entertainment.csv')
with p.open(encoding='utf-8-sig',newline='') as f:r=csv.DictReader(f);cols=r.fieldnames;rows=list(r)
keys={(x['brand'].lower(),x['model'].lower()) for x in rows}
def add(brand,model,name,typ,desc,spec,url,source,year,date='',price='',currency='',ptype='',market='',notes=''):
 if (brand.lower(),model.lower()) in keys:return
 keys.add((brand.lower(),model.lower()))
 rows.append(dict(category_code='C',department='TVs, Video & Home Entertainment',subcategory='Projectors',product_type=typ,product_name=name,manufacturer=brand,brand=brand,model=model,manufacturer_part_number=model,gtin='',description=desc,specifications_json=json.dumps(spec,separators=(',',':')),image_url='',product_url=url,release_date=date,release_date_precision='day' if len(date)==10 else 'year',release_year=year,official_price=price,price_currency=currency,price_type=ptype,price_market=market,price_source_url=source if price else '',product_source_url=source,source_attribution='Official manufacturer launch announcement/product page',collected_on='2026-10-13',verification_status='official_manufacturer_source_verified',notes=notes+' Official image URL not captured; confirm from product gallery before import.'))
add('Optoma','GT4000UHD','Optoma GT4000UHD 4K UHD Laser Ultra Short Throw Projector','Ultra-short-throw home entertainment projector','Compact 4K UHD laser UST projector for gaming and home entertainment.',{'resolution':'4K UHD','light_source':'Laser','brightness_lumens':4000,'contrast_ratio':'500000:1','throw':'100 inch image from under 12 inches; 120 inch max'},'https://www.optomausa.com/product/gt4000uhd','https://www.optomausa.com/latest-news/gt4000uhd','2025','2025-05-06',notes='Official Optoma launch announcement dated May 6 2025; public price not captured.')
add('NEBULA','Cosmos 4K SE','soundcore Nebula Cosmos 4K SE Projector','Portable 4K smart projector','4K UHD smart projector with hybrid laser/LED light source, Google TV and Dolby Vision.',{'resolution':'3840x2160','brightness_ansi_lumens':1800,'light_source':'Hybrid laser + LED','screen_max_inch':200,'hdr':'Dolby Vision','smart_platform':'Google TV with Netflix','audio':'2 x 15 W; Dolby Audio','ports':['HDMI 2.1 eARC','HDMI 2.1','USB-A','AUX'],'weight_kg':4.5},'https://www.ankerjapan.com/products/d2342','https://www.anker-in.com/posts/nebula-introduces-cosmos-4k-se-and-capsule-air-projectors-to-meet-different-cinematic-needs-from-high-resolution-to-flexible-viewing-options','2024','2024-08-29','1299.99','USD','announcement_msrp','United States','Anker lists US MSRP $1,299.99 and availability from Aug 29 2024; Japan sale began Oct 3 2024 at JPY 199,900.')
add('NEBULA','Capsule Air','soundcore Nebula Capsule Air Portable Projector','Portable 720p smart projector','Small portable projector with battery and adjustable snap-on base.',{'resolution':'1280x720','brightness_ansi_lumens':150,'projection_max_inch':100,'battery':'34 Wh; up to 2 hours','smart_platform':'Google TV with Netflix','weight_oz':22.93},'https://www.anker-in.com/posts/nebula-introduces-cosmos-4k-se-and-capsule-air-projectors-to-meet-different-cinematic-needs-from-high-resolution-to-flexible-viewing-options','https://www.anker-in.com/posts/nebula-introduces-cosmos-4k-se-and-capsule-air-projectors-to-meet-different-cinematic-needs-from-high-resolution-to-flexible-viewing-options','2024','2024-08-29','349.99','USD','announcement_msrp','United States','Anker lists MSRP $349.99 and US availability Aug 29 2024; exact product URL not captured.')
with p.open('w',encoding='utf-8-sig',newline='') as f:w=csv.DictWriter(f,fieldnames=cols);w.writeheader();w.writerows(rows)
print('C rows',len(rows))
